PS X:\Program Files\WindowsPowerShell\PowerShell-7.6.8-win-x64> Get-ChildItem -Path "X:\Windows\System32\drivers" -File -Include "*hv*","*vid*","*vmbus*","*whp*","*wsl*","*lxcore*" -ErrorAction SilentlyContinue |
Select-Object -Property @(
    "Name",
    @{Name="Surum"; Expression={$_.VersionInfo.FileVersion}},
    @{Name="Boyut_KB"; Expression={[math]::Round($_.Length / 1KB, 2)}}
) | Format-Table -AutoSize
